package com.badrulamin.University_Management.controller;  import com.badrulamin.University_Management.entity.AcademicResult; import com.badrulamin.University_Management.service.AcademicResultService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;  import com.badrulamin.University_Management.payload.response.PagedResponse; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.data.domain.Sort; import org.springframework.web.bind.annotation.RequestParam;  import java.util.List;  @RestController @RequestMapping("/api/academic-results") @RequiredArgsConstructor public class AcademicResultController {      private final AcademicResultService academicResultService;      @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     @GetMapping     public ResponseEntity<PagedResponse<AcademicResult>> findAll(             @RequestParam(defaultValue = "0") int page,             @RequestParam(defaultValue = "20") int size,             @RequestParam(defaultValue = "id") String sortBy,             @RequestParam(defaultValue = "asc") String sortDir) {         Sort sort = sortDir.equalsIgnoreCase("desc") ? Sort.by(sortBy).descending() : Sort.by(sortBy).ascending();         Pageable pageable = PageRequest.of(page, size, sort);         Page<AcademicResult> paged = academicResultService.findAll(pageable);         PagedResponse<AcademicResult> response = new PagedResponse<>(paged.getContent(), paged.getNumber(), paged.getSize(), paged.getTotalElements(), paged.getTotalPages(), paged.isFirst(), paged.isLast());         return ResponseEntity.ok(response);     }      @GetMapping("/{id}")     @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     public ResponseEntity<AcademicResult> findById(@PathVariable Long id) {         return ResponseEntity.ok(academicResultService.findById(id));     }      @PostMapping     @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     public ResponseEntity<AcademicResult> save(@Valid @RequestBody AcademicResult academicResult) {         return ResponseEntity.ok(academicResultService.save(academicResult));     }      @PutMapping("/{id}")     @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     public ResponseEntity<AcademicResult> update(@PathVariable Long id, @Valid @RequestBody AcademicResult academicResult) {         return ResponseEntity.ok(academicResultService.update(id, academicResult));     }      @DeleteMapping("/{id}")     @PreAuthorize("hasAuthority('ACADEMIC_VIEW')")     public ResponseEntity<Void> delete(@PathVariable Long id) {         academicResultService.delete(id);         return ResponseEntity.noContent().build();     } }